python3 -c "from pathlib import Path; p=Path('programs/task-0ae06a69.py'); p.write_text('def transform(grid):
    # The straight separator marks the target color; repeated matching objects are
    # converted to the separator color. Determine the non-background singleton line.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    line = None
    for r, row in enumerate(grid):
        vals = set(row) - {bg}
        if len(vals) == 1 and row.count(next(iter(vals))) >= 3:
            # horizontal separator candidates span a substantial fraction of width
            col = next(iter(vals))
            if row.count(col) >= max(3, w // 5): line = col
    for c in range(w):
        vals = {grid[r][c] for r in range(h)} - {bg}
        if len(vals) == 1:
            col = next(iter(vals))
            if sum(grid[r][c] == col for r in range(h)) >= max(3, h // 5): line = col
    if line is None: return [row[:] for row in grid]
    return [[line if v not in (bg, line) and v != 3 else v for v in row] for row in grid]
')"

