python3 -c "from pathlib import Path; p=Path('programs/task-0ae06a69.py'); p.write_text('def transform(grid):
    # Complete the interrupted line formed by the sparse color-3 markers.
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Color 3 is used for isolated line endpoints; connect aligned gaps only.
    for r in range(h):
        cols = [c for c,v in enumerate(grid[r]) if v == 3]
        if len(cols) >= 2:
            a,b=min(cols),max(cols)
            if all(grid[r][c] in (3,6) for c in range(a,b+1)):
                for c in range(a,b+1):
                    if out[r][c] == 6: out[r][c]=3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 3]
        if len(rows) >= 2:
            a,b=min(rows),max(rows)
            if all(grid[r][c] in (3,6) for r in range(a,b+1)):
                for r in range(a,b+1):
                    if out[r][c] == 6: out[r][c]=3
    return out
')"

